!function(t){function r(r){for(var p,n,o=r[0],m=r[1],c=r[2],u=0,j=[];u<o.length;u++)n=o[u],Object.prototype.hasOwnProperty.call(a,n)&&a[n]&&j.push(a[n][0]),a[n]=0;for(p in m)Object.prototype.hasOwnProperty.call(m,p)&&(t[p]=m[p]);for(s&&s(r);j.length;)j.shift()();return i.push.apply(i,c||[]),e()}function e(){for(var t,r=0;r<i.length;r++){for(var e,n=i[r],o=!0,m=1;m<n.length;m++)e=n[m],0!==a[e]&&(o=!1);o&&(i.splice(r--,1),t=p(p.s=n[0]))}return t}function p(r){if(n[r])return n[r].exports;var e=n[r]={i:r,l:!1,exports:{}};return t[r].call(e.exports,e,e.exports,p),e.l=!0,e.exports}var n={},a={11:0},i=[];p.m=t,p.c=n,p.d=function(t,r,e){p.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:e})},p.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},p.t=function(t,r){if(1&r&&(t=p(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var e=Object.create(null);if(p.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var n in t)p.d(e,n,function(r){return t[r]}.bind(null,n));return e},p.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return p.d(r,"a",r),r},p.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},p.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=r,o=o.slice();for(var c=0;c<o.length;c++)r(o[c]);var s=m;i.push([14,0]),e()}({14:function(t,r,e){"use strict";e.r(r);var p=e(0);Object(p.a)("jp","army",e(16),e(1))},16:function(t){t.exports=JSON.parse('{"category":[{"name":"日本","link":"jp_shortcut"},{"name":"陆战武器","link":"jp_army"},{"name":"坦克","link":"jp_army#jp_army_tank"}],"model":"94式小型坦克","description":"<h6>综述：</h6><p>94式是日军的一种小型坦克（日本将车重5t以下的坦克称小型坦克），它于1933年左右问世，1936年正式装备日军，主是提供给日军作侦察、装甲运输、步兵支援与机动奔袭用。94式坦克是日本基于维克斯公司20世纪20年代的坦克所设计，属最早期坦克，因此整体性能较差，除了装甲、火力薄弱外，在运行设计上也存在一些问题，如炮塔需要人手转动，乘员观察视野不广，因炮塔空间小，在机枪向前瞄准时，驾驶员就无法推开出口舱盖等；由于此坦克既小又弱，故被称之为“豆坦克”。94式坦克造价低，到1937年止，一共生产了800多辆；该型坦克在二战前本该要被淘汰，但因为日军的坦克严重缺乏，因此一直到二战爆发后仍有日军部队在使用。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}1944年2月，马绍尔群岛埃尼威托克岛战斗中日本陆军的一辆94式小型坦克。{{image}}imgs/jp/army/jp_army_tank94_11.jpg{{text}}1939年，驻扎蒙古的日本关东军第3坦克团一辆94式小型坦克。{{image}}imgs/jp/army/jp_army_tank94_12.jpg{{text}}1945年缅甸战场，日军第14坦克团的一辆94式小型坦克。{{image}}imgs/jp/army/jp_army_tank94_13.jpg","description":"<h6>94式小型坦克</h6><p>94式小型坦克的装甲薄弱、重机枪子弹或一束手榴弹在近距离就能将它击穿或击毁；它没装火炮，火力只有一挺7.7mm机枪，根本无法作远距离攻击，不过，该坦克车速较快，车体小，可在一些狭窄的空间快速穿行。</p><p>该型坦克坦克参数：</p><p>车长：3.37m，车宽：1.62m，车高：1.77m，车重：3.55t；</p><p>最高车速：40km/h，最大行程：约160km;</p><p>装甲厚度：4-12mm;</p><p>武器：一挺7.7mm机枪</p><p>乘员：2人。</p>","caption":""}],"part2title":"战场上的94式小型坦克","part2description":"<p>日军94式小型坦克参加过1939年远东地区的诺门罕战役，但在苏军的坦克面前，根本无还手之力。在1937年开始的日军侵华战争中，有100多辆94式坦克组成多个战车中队配属日军陆军作战，如对南京城的进攻中，就有藤田战车中队的50多辆94式坦克， 而正是藤田实彦指挥的战车队引导日军冲入南京城开始了对中国军民实施大屠杀。在战场上，94式小型坦克经常与89式中型坦克配合作战，94式负责用机枪对付冲上来的爆炸手，89式则负责展开炮火攻击，当时由于中国军队缺少反坦克火力，才使这些豆坦克能在中国大地上横冲直撞。</p><p>94式也参加了日军入侵东南亚国家的战斗，在太平洋战事发生后，在菲律宾及太平洋海岛的战斗中，94式坦克在美军的坦克火炮和反坦克炮火前简直是不堪一击。</p>","part2content":[{"image":"imgs/jp/army/jp_army_tank94_31.jpg","description":"1937年12月，日军山田部队的94式坦克对南京城的中华门进行疯狂攻击。","caption":""},{"image":"imgs/jp/army/jp_army_tank94_32.jpg","description":"1938年，日军第10师团的94式坦克正在支援日军步兵进攻中国台儿庄。","caption":""},{"image":"imgs/jp/army/jp_army_tank94_33.jpg","description":"1941年湖南长沙会战，日军的94式坦克正在涉水渡河。","caption":""},{"image":"imgs/jp/army/jp_army_tank94_34.jpg","description":"1940-1941年间，侵华日军的94式坦克在中国某地集结。","caption":""},{"image":"imgs/jp/army/jp_army_tank94_35.jpg","description":"1941年，日军的94式坦克在中国华南沿海地区登陆。","caption":""},{"image":"imgs/jp/army/jp_army_tank94_36.jpg","description":"1941年底，在菲律宾战场上的日军94式坦克。","caption":""},{"image":"imgs/jp/army/jp_army_tank94_37.jpg","description":"1945年，在中国东北，苏军缴获日本关东军的一批94式小型坦克。","caption":""}]}')}});